 // OMEGA-BLOCK-START
 // Computes C = A * B on the calling thread. C is NOT zeroed by the caller.
 // n is any size from 1 to 2048.
-extern "C" void matmul(int n, const float* A, const float* B, float* C) {
-    for (int i = 0; i < n; ++i)
-        for (int j = 0; j < n; ++j) {
-            float s = 0.0f;
-            for (int k = 0; k < n; ++k) s += A[i * n + k] * B[k * n + j];
-            C[i * n + j] = s;
+extern "C" void matmul(int n, const float* __restrict__ A, const float* __restrict__ B, float* __restrict__ C) {
+    for (int i = 0; i < n; ++i) {
+        float* __restrict__ ci = C + i * n;
+        const float* __restrict__ ai = A + i * n;
+        for (int j = 0; j < n; ++j) ci[j] = 0.0f;
+        for (int k = 0; k < n; ++k) {
+            float aik = ai[k];
+            const float* __restrict__ bk = B + k * n;
+            int j = 0;
+            #if defined(__ARM_NEON)
+            float32x4_t v_aik = vdupq_n_f32(aik);
+            for (; j <= n - 4; j += 4) {
+                float32x4_t v_bk = vld1q_f32(&bk[j]);
+                float32x4_t v_ci = vld1q_f32(&ci[j]);
+                v_ci = vfmaq_f32(v_ci, v_aik, v_bk);
+                vst1q_f32(&ci[j], v_ci);
+            }
+            #endif
+            for (; j < n; ++j) {
+                ci[j] += aik * bk[j];
+            }
         }
+    }
 }
 // OMEGA-BLOCK-END
